(function () {
    function init() {
        const container =
            document.getElementById('scroll-gallery') ||
            document.getElementById('infinite-scroll-gallery');

        if (!container || Util.isMobile()) {
            if (!container) {
                console.warn('justified-gallery: container not found.');
            }
            return;
        }

        const config = {
            targetRowHeight: parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-target-row-height')) || 225,
            gap: parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--jg-gap')) || 4,
            justifyLastRow: false,
            resizeDebounce: 120,
            mutationDebounce: 120,
            scrollBottomThreshold: 200 // px from bottom to trigger a catch-up layout
        };

        // --- utilities ---
        const debounce = (fn, wait) => {
            let t;
            return (...args) => {
                clearTimeout(t);
                t = setTimeout(() => fn.apply(this, args), wait);
            };
        };

        const itemAspectRatio = el => {
            const img = el.querySelector('img');
            if (!img) return 1;
            if (img.dataset?.aspect) return +img.dataset.aspect || 1;
            if (img.hasAttribute('width') && img.hasAttribute('height')) {
                const w = +img.getAttribute('width');
                const h = +img.getAttribute('height');
                if (w > 0 && h > 0) return w / h;
            }
            return (img.naturalWidth && img.naturalHeight) ? img.naturalWidth / img.naturalHeight : 1;
        };

        const availableContentWidth = el => {
            const rect = el.getBoundingClientRect();
            const cs = getComputedStyle(el);
            const padLeft = parseFloat(cs.paddingLeft) || 0;
            const padRight = parseFloat(cs.paddingRight) || 0;
            return Math.max(1, rect.width - padLeft - padRight);
        };

        const waitForSectionImages = async sectionEl => {
            const imgs = [...sectionEl.querySelectorAll('img')];
            if (!imgs.length) return;
            await Promise.all(imgs.map(img => {
                if (img.dataset?.aspect) return Promise.resolve();
                if (img.decode) return img.decode().catch(() => {});
                if (img.complete && img.naturalWidth) return Promise.resolve();
                return new Promise(res => { img.onload = img.onerror = res; });
            }));
        };

        // --- layout ---
        function layoutDateBody(dateBodyEl) {
            if (!dateBodyEl) return;
            const gap = config.gap;
            const containerWidth = availableContentWidth(dateBodyEl);
            const itemEls = [...dateBodyEl.querySelectorAll('.photo-thumbnail-container')];
            if (!itemEls.length) return;

            // reset only if present
            for (const el of itemEls) {
                if (el.style.width || el.style.height || el.style.marginRight || el.style.marginBottom) {
                    el.style.width = '';
                    el.style.height = '';
                    el.style.marginRight = '';
                    el.style.marginBottom = '';
                }
                el.style.boxSizing = 'border-box';
                el.style.flex = '0 0 auto';
                el.style.display = 'block';
            }

            const items = itemEls.map(el => ({ el, aspect: itemAspectRatio(el) || 1 }));

            const rows = [];
            let row = [];
            let sum = 0;
            const targetH = config.targetRowHeight;

            items.forEach((it, idx) => {
                row.push(it);
                sum += it.aspect;
                const rowW = sum * targetH + (row.length - 1) * gap;
                if (rowW >= containerWidth || idx === items.length - 1) {
                    rows.push({ items: row.slice(), aspectSum: sum, isLast: idx === items.length - 1 });
                    row = [];
                    sum = 0;
                }
            });

            rows.forEach(r => {
                const totalGap = (r.items.length - 1) * gap;

                if (r.isLast && !config.justifyLastRow) {
                    const height = targetH;
                    r.items.forEach((it, i) => {
                        const w = it.aspect * height;
                        it.el.style.width = w.toFixed(3) + 'px';
                        it.el.style.height = height.toFixed(3) + 'px';
                        it.el.style.marginRight = i < r.items.length - 1 ? gap + 'px' : '0px';
                        it.el.style.marginBottom = gap + 'px';
                    });
                } else {
                    const height = (containerWidth - totalGap) / r.aspectSum;
                    let used = 0;
                    r.items.forEach((it, i) => {
                        const w = it.aspect * height;
                        used += w;
                        it.el.style.width = w.toFixed(3) + 'px';
                        it.el.style.height = height.toFixed(3) + 'px';
                        it.el.style.marginRight = i < r.items.length - 1 ? gap + 'px' : '0px';
                        it.el.style.marginBottom = gap + 'px';
                    });
                    // distribute rounding discrepancy to the last item
                    const discrepancy = (containerWidth - totalGap) - used;
                    if (Math.abs(discrepancy) >= 0.001 && r.items.length) {
                        const lastEl = r.items[r.items.length - 1].el;
                        const current = parseFloat(lastEl.style.width) || 0;
                        lastEl.style.width = (current + discrepancy).toFixed(3) + 'px';
                    }
                }
            });
        }

        const layoutAllSections = () => {
            const rows = container.querySelectorAll('.row.image-group-padding');
            rows.forEach(r => layoutDateBody(r));
        };

        const debouncedLayoutAll = debounce(layoutAllSections, config.resizeDebounce);

        async function waitAndLayoutRow(rowEl) {
            try { await waitForSectionImages(rowEl); } catch {}
            layoutDateBody(rowEl);
        }

        let contentAppendedCallback = null;
        const setContentAppendedCallback = cb => { contentAppendedCallback = typeof cb === 'function' ? cb : null; };

        // --- observer machinery with pending queue ---
        let mo = null, observing = false, pendingRows = new Set();

        const mutationHandler = mutations => {
            const addedRows = new Set();
            let newContent = false;

            for (const m of mutations) {
                if (m.type !== 'childList') continue;

                m.addedNodes.forEach(node => {
                    if (!(node instanceof Element)) return;

                    // date containers / rows
                    if (node.classList.contains('dateContainer')) {
                        const row = node.querySelector('.row.image-group-padding');
                        if (row) { addedRows.add(row); newContent = true; }
                    } else if (node.matches?.('.row.image-group-padding')) {
                        addedRows.add(node); newContent = true;
                    } else {
                        node.querySelectorAll?.('.row.image-group-padding').forEach(r => { addedRows.add(r); newContent = true; });
                    }

                    // thumbnails
                    if (node.matches?.('.photo-thumbnail-container')) {
                        const rowParent = node.closest('.row.image-group-padding');
                        if (rowParent) { addedRows.add(rowParent); newContent = true; }
                    } else {
                        node.querySelectorAll?.('.photo-thumbnail-container').forEach(n => {
                            const rowParent = n.closest('.row.image-group-padding');
                            if (rowParent) { addedRows.add(rowParent); newContent = true; }
                        });
                    }
                });
            }

            if (addedRows.size) {
                addedRows.forEach(r => {
                    if (observing) {
                        // immediate layout to avoid debounce lag under fast scroll
                        waitAndLayoutRow(r);
                    } else {
                        pendingRows.add(r);
                    }
                });
            } else {
                layoutAllSections();
            }

            if (newContent && contentAppendedCallback) {
                try { contentAppendedCallback(); } catch (e) { console.error('contentAppendedCallback error', e); }
            }
        };

        const onMutations = debounce(mutationHandler, config.mutationDebounce);

        const startObserving = () => {
            if (!mo) mo = new MutationObserver(onMutations);
            if (!observing) {
                mo.observe(container, { childList: true, subtree: true });
                observing = true;
            }
            // flush rows captured while disconnected
            if (pendingRows.size) {
                const rows = [...pendingRows];
                pendingRows.clear();
                rows.forEach(r => waitAndLayoutRow(r));
            }
        };

        const stopObserving = () => {
            if (mo && observing) {
                try { mo.disconnect(); } catch {}
                observing = false;
            }
        };

        // --- near-bottom scroll catch-up ---
        const onScrollCatchUp = () => {
            const scrollY = window.scrollY || document.documentElement.scrollTop || 0;
            const viewportH = window.innerHeight || document.documentElement.clientHeight;
            const docH = Math.max(
                document.body.scrollHeight, document.documentElement.scrollHeight,
                document.body.offsetHeight, document.documentElement.offsetHeight,
                document.body.clientHeight, document.documentElement.clientHeight
            );
            const distanceToBottom = docH - (scrollY + viewportH);
            if (distanceToBottom <= config.scrollBottomThreshold) {
                layoutAllSections();
            }
        };
        const debouncedScrollCatchUp = debounce(onScrollCatchUp, 100);

        // --- public API ---
        window.ScrollJustifiedGalleryInfinite = {
            layoutAll: layoutAllSections,
            waitForSectionImages,
            setContentAppendedCallback,
            disconnectObserver: stopObserving,
            reconnectObserver: startObserving
        };

        // --- initial layout ---
        setTimeout(() => {
            const rows = [...container.querySelectorAll('.row.image-group-padding')];
            if (!rows.length) { layoutAllSections(); startObserving(); return; }
            Promise.all(rows.map(waitForSectionImages)).finally(() => {
                layoutAllSections();
                startObserving();
            });
        }, 20);

        // --- listeners ---
        window.addEventListener('resize', debouncedLayoutAll);
        window.addEventListener('scroll', debouncedScrollCatchUp, { passive: true });

        const resizeObserver = new ResizeObserver(debouncedLayoutAll);
        resizeObserver.observe(container);
    } // end init

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
